steps.command:
mkdir -p /srv/app && cat > /srv/app/pool.pl <<'PERLEOF'
use strict; use warnings;
my @pids;
for my $i (0..3) {
    my $pid = fork(); die "fork: $!" unless defined $pid;
    if (!$pid) {
        open(my $f, '>', "/srv/app/worker-$i.out") or die $!;
        print $f "worker $i handled 25 jobs\n";
        close $f;
        select(undef, undef, undef, 0.3);
        exit 0;
    }
    push @pids, $pid;
}
waitpid($_, 0) for @pids;
print "reaped ", scalar(@pids), " workers\n";
PERLEOF
perl -c /srv/app/pool.pl
